style.css:
@-moz-document domain("tracker.egamings.com") {
/* Сообщения без тегов (просто заметки) */
  #history .journal.has-notes:not(.has-details):not(.private-notes) {
    width: 50%;
    margin: 0 auto 25px;
    float: none;
    box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px;
  }

  /* Сообщения с тегами */
  #history .journal.has-notes.has-details:not(.private-notes) {
    width: 50%;
    margin: 0 auto 25px;
    float: none;
    box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px;
  }

  /* Приватные сообщения без тегов */
  #history .journal.has-notes.private-notes:not(.has-details) {
    width: 50%;
    margin: 0 auto 25px;
    float: left;
    box-shadow: 0 0 0 2px rgba(120, 72, 48, 0.1);
    border: 1px solid rgba(0,0,0,0.05);
    border-radius: 6px;
    background-color: #f2f2f2;
}

  /* Приватные сообщения с тегами */
  #history .journal.has-notes.private-notes.has-details {
    width: 20%;
    margin: 0 auto 25px;
    float: left;
    box-shadow: 0 0 0 2px rgba(120, 72, 48, 0.1);
    border: 1px solid rgba(0,0,0,0.05);
    border-radius: 6px;
    background-color: #f2f2f2;
  }

  /* Только смена тегов (без заметок) */
  #history .journal.has-details:not(.has-notes) {
    width: 20%;
    margin: 0 auto 25px;
    float: left;
    box-shadow: 0 0 0 2px rgba(120, 72, 48, 0.1);
    border: 1px solid rgba(0,0,0,0.05);
    border-radius: 6px;
    background-color: #f2f2f2;
  }

  /* Основной блок задачи */
  #content .issue.details {
    padding: 30px;
    background: #ffffdf;
    box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px;
  }

#content .journal .wiki {
  padding: 15px;
}

.journal {
    position: relative;
    margin-bottom: 20px;
    border: 1px solid #d1d3e0;
    border-radius: 3px;
    margin-left: 36px
}

.journal.changeset h4+p {
    margin-bottom: 0;
    padding-bottom: 8px;
    background-color: #f9fafb;
    font-size: .92em
}

.journal.changeset h4+p>a:first-child {
    font-family: Menlo,Consolas,Roboto Mono,Ubuntu Monospace,Noto Mono,Oxygen Mono,Liberation Mono,monospace;
    font-weight: 600
}

.journal>div:target {
    position: relative;
    margin-top: -58px;
    padding-top: 58px
}

.journal>div:target::before {
    content: "";
    display: block;
    position: absolute;
    top: 58px;
    right: 0;
    bottom: 0;
    left: 0;
    border-radius: 2px;
    box-shadow: 0 0 0 1px #512dc4,0 0 0 4px rgba(81,45,196,.2);
    pointer-events: none
}

.journal>div:target>h4::before {
    border-right-color: #512dc4;
    filter: drop-shadow(-4px 0 0 rgba(81, 45, 196, 0.2))
}

@media screen and (min-width: 900px) {
    .journal>div:target {
        margin-top:-20px;
        padding-top: 20px
    }

    .journal>div:target::before {
        top: 20px
    }
}

.journal>div>.contextual,.journal>.contextual {
    position: relative;
    z-index: 1;
    margin: 0;
    padding: 8px 12px;
    font-size: .92em
}

.journal>div>.contextual>a.journal-link,.journal>.contextual>a.journal-link {
    padding-left: 5px;
    opacity: 1;
    color: #707893
}

.journal>div>.contextual>a.journal-link::before,.journal>.contextual>a.journal-link::before {
    content: "";
    display: none
}

.journal>div>h4,.journal>h4 {
    margin: 0;
    padding: 8px 12px;
    border-radius: 3px 3px 0 0;
    background-color: #f9fafb;
    color: #707893;
    font-size: .92em;
    font-weight: normal
}

.journal>div>h4 a,.journal>h4 a {
    color: #212136
}

.journal>div>h4 a.user,.journal>h4 a.user {
    font-weight: 600
}

.journal>div>h4 .journal-link,.journal>h4 .journal-link {
    color: #707893
}

.journal>div>h4,.journal>h4 {
    position: relative
}

.journal>div>h4::before,.journal>div>h4::after,.journal>h4::before,.journal>h4::after {
    content: " ";
    display: block;
    position: absolute;
    top: 9px;
    right: 100%;
    left: -14px;
    width: 0;
    height: 0;
    border-style: solid solid outset;
    border-color: rgba(0,0,0,0);
    pointer-events: none
}

.journal>div>h4::after,.journal>h4::after {
    margin-top: 1px;
    margin-left: 2px;
    border-width: 6px;
    border-right-color: #f9fafb
}

.journal>div>h4::before,.journal>h4::before {
    border-width: 7px;
    border-right-color: #d1d3e0
}

.journal>div>h4>.gravatar,.journal>h4>.gravatar {
    top: 0;
    margin-top: -4px;
    margin-left: -49px;
    float: left
}

.journal>p {
    padding-right: 12px;
    padding-left: 12px
}

.journal>p:empty {
    margin-bottom: 0
}

.journal form,.journal .wiki,.journal .details {
    border-top: 1px solid #d1d3e0;
}

.journal .details {
    margin: 0;
    padding: 8px 0;
    padding-left: 32px;
    font-size: .92em
}

.journal .details img {
    margin: 0 0 -3px 4px
}

.journal .thumbnails {
    margin: 0;
    padding: 0 12px 8px
}

.journal .thumbnails img {
    vertical-align: middle
}

.journal .wiki {
    padding: 15px;
}

.journal form {
    padding: 8px 12px 12px;
    background-color: #f9fafb
}

.journal form>p {
    margin-bottom: 15px
}

.journal form>p:last-child {
    margin-bottom: 0
}

.journal form>label {
    display: inline-block;
    margin-bottom: 10px;
    line-height: 1.428571429
}

.journal form>.wiki {
    margin: 0 -15px -15px;
    padding: 0;
    border: 0 none
}

.journal form>.wiki .preview {
    padding: 15px
}
#sidebar {
flex: 0 0 290px;
}
table th, table td {
    padding: 0px 2px;
}
table {
  border-collapse: separate;
    text-indent: initial;
    border-spacing: 0px;
}
table.list td {
    padding: 1px;
  }
}
